// The six fields this workflow exists to fill.
const CORE = ['company', 'title', 'phone', 'industry', 'employee_count', 'technologies'];
const blank = v => v === null || v === undefined || (Array.isArray(v) ? v.length === 0 : String(v).trim() === '');

// Callers name fields their own way; take the common spellings and move on.
const raw = $input.first().json.body ?? {};
const src = raw.lead && typeof raw.lead === 'object' ? raw.lead : raw;
const pick = (...keys) => {
  for (const k of keys) if (!blank(src[k])) return typeof src[k] === 'string' ? src[k].trim() : src[k];
  return null;
};

const lead = {
  email: pick('email', 'work_email', 'workEmail'),
  first_name: pick('first_name', 'firstName', 'firstname'),
  last_name: pick('last_name', 'lastName', 'lastname'),
  name: pick('name', 'full_name', 'fullName'),
  company: pick('company', 'company_name', 'companyName', 'organization'),
  title: pick('title', 'job_title', 'jobTitle', 'jobtitle'),
  phone: pick('phone', 'phone_number', 'phoneNumber'),
  industry: pick('industry'),
  employee_count: pick('employee_count', 'employees', 'employeeCount', 'company_size'),
  technologies: pick('technologies', 'tech', 'technographics'),
  website: pick('website', 'domain', 'company_website', 'url'),
  linkedin_url: pick('linkedin_url', 'linkedin', 'linkedinUrl'),
};
if (typeof lead.technologies === 'string') lead.technologies = lead.technologies.split(/[;,]/).map(t => t.trim()).filter(Boolean);
if (lead.email) lead.email = String(lead.email).toLowerCase();
lead.name = lead.name ?? ([lead.first_name, lead.last_name].filter(Boolean).join(' ') || null);

// A consumer mailbox says nothing about the employer.
const FREE_MAIL = new Set([
  'gmail.com', 'googlemail.com', 'yahoo.com', 'yahoo.co.in', 'yahoo.co.uk', 'ymail.com', 'hotmail.com',
  'outlook.com', 'live.com', 'msn.com', 'icloud.com', 'me.com', 'aol.com', 'proton.me', 'protonmail.com',
  'gmx.com', 'gmx.de', 'mail.com', 'yandex.com', 'zoho.com', 'rediffmail.com', 'qq.com', '163.com',
]);
const hostOf = v => {
  if (blank(v)) return null;
  try { return new URL(/^https?:\/\//i.test(v) ? v : 'https://' + v).hostname.replace(/^www\./, '').toLowerCase(); }
  catch { return null; }
};
const emailDomain = lead.email?.includes('@') ? lead.email.split('@')[1] : null;
const domain = hostOf(lead.website) ?? (emailDomain && !FREE_MAIL.has(emailDomain) ? emailDomain : null);

const missing = CORE.filter(f => blank(lead[f]));
let action = 'enrich', statusCode = 200, body = null;
if (!missing.length) {
  action = 'respond';
  body = { status: 'complete', lead, filled: [], missing: [], sources: {} };
} else if (!domain && !lead.company) {
  action = 'respond';
  statusCode = 422;
  body = { status: 'not_enough_to_go_on', error: 'Send a work email, a website or a company name.', lead };
}
return [{ json: { lead, domain, missing, action, statusCode, body } }];

