// One Serper query per item: the company's LinkedIn page (size, industry) and,
// when there is a name, the person's (title). The model decides later whether
// what came back is actually this person and this company.
const { lead, domain } = $('Read lead').first().json;
const page = $('Firecrawl: homepage').isExecuted ? $('Firecrawl: homepage').first().json.body?.data : null;
const company = lead.company ?? page?.metadata?.ogSiteName ?? (domain ? domain.split('.')[0] : null);

const queries = [{ kind: 'company', q: 'site:linkedin.com/company "' + company + '"' }];
if (lead.name) queries.push({ kind: 'person', q: 'site:linkedin.com/in "' + lead.name + '" ' + company });
return queries.map(json => ({ json, pairedItem: { item: 0 } }));

// Code only fetches and trims; reading the evidence and deciding what is true
// about this lead is the model's job.
const { lead, domain } = $('Read lead').first().json;
const errors = [];
const sections = [];

if ($('Firecrawl: homepage').isExecuted) {
  const res = $('Firecrawl: homepage').first().json;
  const data = res.statusCode === 200 ? res.body?.data : null;
  if (!data) errors.push('Firecrawl: ' + (res.error?.message ?? 'HTTP ' + res.statusCode + ' ' + JSON.stringify(res.body ?? '').slice(0, 200)));
  else {
    const html = data.rawHtml ?? '';
    const all = (re, max) => [...html.matchAll(re)].map(m => (m[1] ?? m[0]).trim()).filter(Boolean).slice(0, max);
    const uniq = xs => [...new Set(xs)];
    sections.push([
      '## Company homepage: https://' + domain,
      'Title: ' + (data.metadata?.title ?? ''),
      'Description: ' + (data.metadata?.description ?? ''),
      '', 'Meta tags:', ...all(/<meta\b[^>]*>/gi, 40),
      '', 'Script sources:', ...uniq(all(/<script\b[^>]*\bsrc=["']([^"']+)/gi, 80)),
      '', 'Link hrefs:', ...uniq(all(/<link\b[^>]*\bhref=["']([^"']+)/gi, 40)),
      '', 'Inline script openings:', ...all(/<script\b(?![^>]*\bsrc=)[^>]*>([\s\S]*?)<\/script>/gi, 40).map(t => t.slice(0, 200)),
      '', 'Phone links:', ...uniq(all(/href=["']tel:([^"']+)/gi, 5)),
      '', 'Page text:', (data.markdown ?? '').slice(0, 8000),
    ].join('\n'));
  }
}

const plans = $('Plan searches').all();
$input.all().forEach((item, i) => {
  const res = item.json;
  const q = res.body?.searchParameters?.q ?? plans[i]?.json.q;
  if (res.statusCode !== 200) {
    errors.push('Serper: ' + (res.error?.message ?? 'HTTP ' + res.statusCode + ' ' + JSON.stringify(res.body ?? '').slice(0, 200)));
    return;
  }
  const kg = res.body?.knowledgeGraph;
  const lines = (res.body?.organic ?? []).slice(0, 6).map((r, n) => (n + 1) + '. ' + r.title + ' - ' + r.link + '\n   ' + (r.snippet ?? ''));
  sections.push(['## Google results for: ' + q, ...(kg ? ['Knowledge panel: ' + JSON.stringify(kg).slice(0, 1500)] : []), ...lines].join('\n'));
});

const messages = [
  {
    role: 'system',
    content: [
      'You enrich a sales lead for a CRM from the evidence given: the company homepage and Google results for LinkedIn pages.',
      'For each field return a value and the source it came from: "website", "linkedin_person", "linkedin_company" or "search". Use null for both when the evidence does not show it.',
      '- company: the company name as the company presents it.',
      '- title: the person\'s current job title. Only from a result that is clearly this person (same name) at this company.',
      '- phone: the company\'s main phone number exactly as written; null if none is shown.',
      '- industry: a short label (2-4 words), e.g. "B2B software", "E-commerce - apparel", "Dental clinic".',
      '- employee_count: the headcount or size range as stated (e.g. "51-200" from LinkedIn\'s "Company size"). Never estimate.',
      '- linkedin_url / company_linkedin_url: the profile URLs from the results, only when they clearly match.',
      '- technologies: products the website is built on or runs, recognised from script sources, link hrefs, meta generator tags and inline scripts (e.g. Shopify, WordPress, HubSpot, Google Tag Manager, Google Analytics 4, Meta Pixel, Klaviyo, Intercom, Stripe, Hotjar). Common product names; only what the markup shows.',
      'A wrong value is worse than a missing one. When unsure, return null.',
    ].join('\n'),
  },
  {
    role: 'user',
    content: ['## Lead as received', JSON.stringify(lead, null, 2), ...sections].join('\n\n').slice(0, 30000),
  },
];
return [{ json: { messages, errors, evidenceCount: sections.length }, pairedItem: { item: 0 } }];

