={{ (() => {
  // Model settings live here: $env is blocked on n8n Cloud and Variables ($vars) need a paid plan.
  const MODEL = 'gpt-5-nano';
  const REASONING_EFFORT = 'low';
  const field = { type: 'object', additionalProperties: false, required: ['value', 'source'],
    properties: { value: { type: ['string', 'null'] }, source: { type: ['string', 'null'] } } };
  const fields = ['company', 'title', 'phone', 'industry', 'employee_count', 'linkedin_url', 'company_linkedin_url'];
  return JSON.stringify({
    model: MODEL,
    reasoning_effort: REASONING_EFFORT,
    max_completion_tokens: 3000,
    messages: $json.messages,
    response_format: { type: 'json_schema', json_schema: { name: 'lead_enrichment', strict: true, schema: {
      type: 'object',
      additionalProperties: false,
      required: [...fields, 'technologies'],
      properties: {
        ...Object.fromEntries(fields.map(f => [f, field])),
        technologies: { type: 'array', items: { type: 'string' } }
      }
    } } }
  });
})() }}

