// The six fields this workflow exists to fill.
const CORE = ['company', 'title', 'phone', 'industry', 'employee_count', 'technologies'];
const blank = v => v === null || v === undefined || (Array.isArray(v) ? v.length === 0 : String(v).trim() === '');

const { lead: given, domain } = $('Read lead').first().json;
const errors = [...$('Gather evidence').first().json.errors];
const res = $input.first().json;

let read = null;
if (res.statusCode === 200) {
  try { read = JSON.parse(res.body?.choices?.[0]?.message?.content ?? ''); }
  catch { errors.push('OpenAI: reply was not JSON'); }
} else {
  errors.push('OpenAI: ' + (res.error?.message ?? 'HTTP ' + res.statusCode + ' ' + JSON.stringify(res.body ?? '').slice(0, 200)));
}

// Only blanks are filled: whatever the caller sent is kept as sent.
const lead = { ...given };
const filled = [];
const sources = {};
const fill = (field, value, source) => {
  if (blank(value) || !blank(lead[field])) return;
  lead[field] = typeof value === 'string' ? value.trim() : value;
  filled.push(field);
  sources[field] = source;
};
if (read) {
  for (const f of ['company', 'title', 'phone', 'industry', 'employee_count', 'linkedin_url', 'company_linkedin_url']) {
    fill(f, read[f]?.value, read[f]?.source ?? 'search');
  }
  fill('technologies', (read.technologies ?? []).filter(t => !blank(t)), 'website');
}
if (domain) fill('website', 'https://' + domain, 'email domain');

const missing = CORE.filter(f => blank(lead[f]));
const status = !read ? 'error' : !filled.length ? 'not_found' : missing.length ? 'partial' : 'enriched';
return [{
  json: {
    statusCode: status === 'error' ? 502 : 200,
    body: { status, lead, filled, missing, sources, ...(errors.length ? { errors } : {}) },
  },
  pairedItem: { item: 0 },
}];
